        padding: 20px;
      }

      .toolbar,
      .modal-actions {
        flex-direction: column;
      }

      .button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="page">
    <section class="preview-card" aria-labelledby="image-title">
      <div class="image-frame">
        <span class="badge">Library preview</span>
        <img
          src="https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1400&q=80"
          alt="Workspace scene with a laptop, desk lamp, and notebook"
        />
