      box-shadow: var(--shadow);
      background: var(--surface-strong);
      color: var(--text);
    }

    dialog::backdrop {
      background: var(--overlay);
      backdrop-filter: blur(8px);
    }

    .modal {
      padding: 28px;
    }

    .modal-header {
      display: flex;
